{"files":{"tokenizer.js":"function tokenize(text) {
  var normalized = normalize(text);
  var stopwords = { "a": true, "an": true, "the": true, "and": true, "of": true };
  var tokens = [];
  var current = "";
  for (var i = 0; i < normalized.length; i++) {
    var ch = normalized[i];
    if (/[a-z0-9]/.test(ch)) {
      current += ch;
    } else {
      if (current.length > 0) {
        if (!stopwords[current]) {
          tokens.push(current);
        }
        current = "";
      }
    }
  }
  if (current.length > 0) {
    if (!stopwords[current]) {
      tokens.push(current);
    }
  }
  return tokens;
}

function normalize(text) {
  var s = String(text);
  s = s.normalize("NFKC");
  s = s.toLowerCase();
  s = s.replace(/\s+/g, " ");
  s = s.trim();
  return s;
}

function analyze(text) {
  var tokens = tokenize(text);
  var unique = [];
  var seen = {};
  var frequencies = {};
  for (var i = 0; i < tokens.length; i++) {
    var token = tokens[i];
    if (Object.prototype.hasOwnProperty.call(seen, token)) {
      frequencies[token] = frequencies[token] + 1;
    } else {
      seen[token] = true;
      unique.push(token);
      frequencies[token] = 1;
    }
  }
  var count = tokens.length;
  var summary = count + " tokens; " + unique.length + " unique";
  return { tokens: tokens, count: count, unique: unique, frequencies: frequencies, summary: summary };
}
"},"message":"Tokenizer implemented. tokenize calls normalize, splits on non-alphanumeric characters (including apostrophes and accented letters), discards stopwords after the split (so don't -> don, t), keeps digit runs, and returns input order. normalize does NFKC, lowercase, whitespace collapse to single spaces, trim, no accent removal. analyze returns the exact required object with constructor-safe frequencies via hasOwnProperty. Please review. Normalize.js should export the same normalize function; pipeline.js should use tokenize and analyze."}
